-- Workspace -> Domain -> Resource -> Action. No existing grant is migrated to a new resource.
create table feedx_integrations.resources(
 key text primary key,adapter_key text not null references feedx_integrations.adapters(key),workspace text not null,domain text not null,
 slug text not null,label text not null,description text not null,field_policy text not null,filter_fields jsonb not null,
 implemented boolean not null default false,unique(adapter_key,slug)
);
alter table feedx_integrations.resources enable row level security;
revoke all on feedx_integrations.resources from public,anon,authenticated;
alter table feedx_integrations.capabilities add column resource_key text references feedx_integrations.resources(key),add column mcp_tool text;
update feedx_integrations.capabilities set mcp_tool=tool_id;
alter table feedx_integrations.capabilities alter column mcp_tool set not null;
alter table feedx_integrations.capabilities drop constraint capabilities_action_type_check;
alter table feedx_integrations.capabilities add constraint capabilities_action_type_check check(action_type in ('list','read','search','filter','draft','execute','approve'));


