update feedx_integrations.adapters set tools=tools||'[ {"name":"query_mesti_resources","read_only":true} ]'::jsonb where key='factory_mesti';

create function feedx_integrations.mesti_resource_requirements(p_from date,p_to date) returns setof jsonb language sql stable security definer set search_path=public,pg_temp as $$
select jsonb_build_object('id','cleaning_of_area:'||r.id,'module','cleaning_of_area','label',r.task_name,'requirement_id',r.id,'logical_requirement_id',r.logical_requirement_id,'record_status',r.status,'version',r.version_no,'effective_from',r.effective_from,'effective_until',r.effective_until,'recurrence',r.recurrence_type,'weekdays',to_jsonb(r.recurrence_weekdays),'subject_ids',(select coalesce(jsonb_agg(location_id order by location_id),'[]') from public.factory_mesti_cleaning_requirement_locations where requirement_id=r.id)) from public.factory_mesti_cleaning_requirements r where r.effective_from<=p_to and (r.effective_until is null or r.effective_until>p_from)
union all
select jsonb_build_object('id','cleaning_of_equipment:'||r.id,'module','cleaning_of_equipment','label',r.task_name,'requirement_id',r.id,'logical_requirement_id',r.logical_requirement_id,'record_status',r.status,'version',r.version_no,'effective_from',r.effective_from,'effective_until',r.effective_until,'recurrence',r.recurrence_type,'weekdays',to_jsonb(r.recurrence_weekdays),'subject_ids',(select coalesce(jsonb_agg(equipment_id order by equipment_id),'[]') from public.factory_mesti_equipment_cleaning_requirement_equipment where requirement_id=r.id)) from public.factory_mesti_equipment_cleaning_requirements r where r.effective_from<=p_to and (r.effective_until is null or r.effective_until>p_from)
union all
select jsonb_build_object('id','calibration:'||r.id,'module','calibration','label',r.calibration_type,'requirement_id',r.id,'logical_requirement_id',r.logical_requirement_id,'record_status',r.status,'version',r.version_no,'effective_from',r.effective_from,'effective_until',r.effective_until,'recurrence','interval_months','weekdays','null'::jsonb,'subject_ids',jsonb_build_array(r.equipment_id),'interval_months',r.interval_months) from public.factory_mesti_calibration_requirements r where r.effective_from<=p_to and (r.effective_until is null or r.effective_until>p_from)
union all
select jsonb_build_object('id','waste_disposal:'||r.id,'module','waste_disposal','label','Waste disposal','requirement_id',r.id,'logical_requirement_id',r.logical_requirement_id,'record_status',r.status,'version',r.version_no,'effective_from',r.effective_from,'effective_until',r.effective_until,'recurrence',r.frequency,'weekdays',to_jsonb(r.recurrence_weekdays),'subject_ids',jsonb_build_array(r.location_id),'required_count',r.required_count) from public.factory_mesti_waste_disposal_requirements r where r.effective_from<=p_to and (r.effective_until is null or r.effective_until>p_from)
union all
select jsonb_build_object('id','food_processing_control:'||q.id,'module','food_processing_control','label',q.qc_name,'requirement_id',q.id,'production_sop_id',s.id,'sop_version',s.version,'record_status',s.status,'state_source','SOP publication state','effective_from',s.effective_date,'effective_until',null,'recurrence','production_end','qc_type',q.qc_type,'is_required',q.is_required)
 from public.factory_production_sop_step_qc_checks q join public.factory_production_sop_steps st on st.id=q.sop_step_id join public.factory_production_sops s on s.id=st.sop_id
 where (s.effective_date is null or s.effective_date<=p_to) and (s.status='active' or exists(select 1 from public.factory_productions p where p.production_sop_id=s.id and p.sop_version=s.version and p.status='completed' and p.end_date between p_from and p_to))
union all
select jsonb_build_object('id','food_processing_control:legacy_'||st.id,'module','food_processing_control','label',coalesce(st.qc_label,'Legacy QC point'),'requirement_id',st.id,'production_sop_id',s.id,'sop_version',s.version,'record_status',s.status,'state_source','SOP publication state','effective_from',s.effective_date,'effective_until',null,'recurrence','production_end','legacy_definition',true,'is_required',st.qc_required_before_completion,'measurement_type',st.qc_measurement_type,'minimum',st.qc_minimum,'maximum',st.qc_maximum,'uom',st.qc_uom)
 from public.factory_production_sop_steps st join public.factory_production_sops s on s.id=st.sop_id
 where (st.is_qc_checkpoint or st.qc_required_before_completion or st.qc_measurement_type is not null) and not exists(select 1 from public.factory_production_sop_step_qc_checks q where q.sop_step_id=st.id)
 and (s.effective_date is null or s.effective_date<=p_to) and (s.status='active' or exists(select 1 from public.factory_productions p where p.production_sop_id=s.id and p.sop_version=s.version and p.status='completed' and p.end_date between p_from and p_to))
$$;
revoke all on function feedx_integrations.mesti_resource_requirements(date,date) from public,anon,authenticated;

create function feedx_integrations.mesti_resource_occurrences(p_from date,p_to date) returns setof jsonb language sql stable security definer set search_path=public,pg_temp as $$
select jsonb_build_object('id','cleaning_of_area:'||x.id,'record_id',x.id,'module','cleaning_of_area','label',coalesce(x.requirement_snapshot->>'task_name','Area cleaning'),'business_date',x.due_date,'record_status',x.status,'state_source','factory_mesti_cleaning_occurrences.status','verified_at',x.verified_at,'requirement_id',x.requirement_id,'logical_requirement_id',x.logical_requirement_id,'subject_id',x.location_id,'completed_at',x.completed_at,'verification_state',x.verification_result,'source_type','scheduled') from public.factory_mesti_cleaning_occurrences x where x.due_date between p_from and p_to
union all
select jsonb_build_object('id','cleaning_of_equipment:'||x.id,'record_id',x.id,'module','cleaning_of_equipment','label',coalesce(x.requirement_snapshot->>'task_name','Equipment cleaning'),'business_date',x.due_date,'record_status',x.status,'state_source','factory_mesti_equipment_cleaning_occurrences.status','verified_at',x.verified_at,'requirement_id',x.requirement_id,'logical_requirement_id',x.logical_requirement_id,'subject_id',x.equipment_id,'completed_at',x.completed_at,'verification_state',x.verification_result,'source_type',x.source_type,'production_id',x.production_id) from public.factory_mesti_equipment_cleaning_occurrences x where x.due_date between p_from and p_to
union all
select jsonb_build_object('id','calibration:'||x.id,'record_id',x.id,'module','calibration','label','Calibration record','business_date',x.calibrated_date,'record_status',x.status,'state_source','factory_mesti_calibration_records.status','verified_at',x.verified_at,'requirement_id',x.requirement_id,'logical_requirement_id',x.logical_requirement_id,'subject_id',x.equipment_id,'scheduled_due_date',x.scheduled_due_date,'verification_state',x.status,'source_type','calibration_record') from public.factory_mesti_calibration_records x where x.calibrated_date between p_from and p_to
union all
select jsonb_build_object('id','operator_hygiene:'||x.id,'record_id',x.id,'module','operator_hygiene','label','Operator hygiene session','business_date',x.inspection_date,'record_status',x.status,'state_source','factory_mesti_operator_hygiene_sessions.status','verified_at',x.verified_at,'submitted_at',x.submitted_at,'verification_state',x.status,'source_type','daily_session') from public.factory_mesti_operator_hygiene_sessions x where x.inspection_date between p_from and p_to
union all
select jsonb_build_object('id','waste_disposal:'||x.id,'record_id',x.id,'module','waste_disposal','label','Waste disposal session','business_date',x.disposal_date,'record_status',x.status,'state_source','factory_mesti_waste_disposal_sessions.status','verified_at',x.verified_at,'submitted_at',x.submitted_at,'verification_state',x.status,'source_type','daily_session') from public.factory_mesti_waste_disposal_sessions x where x.disposal_date between p_from and p_to
union all
select jsonb_build_object('id','health_declaration:'||d.business_date,'module','health_declaration','label','Health declaration daily aggregate','business_date',d.business_date,'record_status',null,'state_source','non-voided daily count only','record_count',count(*),'source_type','daily_aggregate') from (select (declared_at at time zone 'Asia/Kuala_Lumpur')::date business_date from public.factory_mesti_health_declarations where voided_at is null and declared_at>=p_from::timestamp at time zone 'Asia/Kuala_Lumpur' and declared_at<(p_to+1)::timestamp at time zone 'Asia/Kuala_Lumpur') d group by d.business_date
union all
select jsonb_build_object('id',m.module||':'||p.id,'record_id',p.id,'module',m.module,'label',m.label,'business_date',p.end_date,'record_status',p.status,'state_source','factory_productions.status','verification_state',case when m.module='food_processing_control' then p.verification_status else null end,'verified_at',case when m.module='food_processing_control' then p.verified_at else null end,'production_id',p.id,'source_type','production_end') from public.factory_productions p cross join (values('food_processing_control','Production compliance record'),('finished_product_storage_control','Storage provenance context'))m(module,label) where p.status='completed' and p.end_date between p_from and p_to
$$;
revoke all on function feedx_integrations.mesti_resource_occurrences(date,date) from public,anon,authenticated;

create function feedx_integrations.mesti_resource_evidence(p_from date,p_to date) returns setof jsonb language sql stable security definer set search_path=public,pg_temp as $$
select jsonb_build_object('id','cleaning_of_area:'||x.id,'record_id',x.id,'module','cleaning_of_area','label','Cleaning evidence','business_date',x.due_date,'record_status',x.status,'requirement_id',x.requirement_id,'logical_requirement_id',x.logical_requirement_id,'verified_at',x.verified_at,'subject_id',x.location_id,'completion_result',x.completion_result,'completed_at',x.completed_at,'verification_state',x.verification_result,'source_type','scheduled') from public.factory_mesti_cleaning_occurrences x where x.due_date between p_from and p_to
union all
select jsonb_build_object('id','cleaning_of_equipment:'||x.id,'record_id',x.id,'module','cleaning_of_equipment','label','Cleaning evidence','business_date',x.due_date,'record_status',x.status,'requirement_id',x.requirement_id,'logical_requirement_id',x.logical_requirement_id,'verified_at',x.verified_at,'subject_id',x.equipment_id,'completion_result',x.completion_result,'completed_at',x.completed_at,'verification_state',x.verification_result,'source_type',x.source_type) from public.factory_mesti_equipment_cleaning_occurrences x where x.due_date between p_from and p_to
union all
select jsonb_build_object('id','calibration:'||x.id,'record_id',x.id,'module','calibration','label','Calibration evidence','business_date',x.calibrated_date,'record_status',x.status,'requirement_id',x.requirement_id,'logical_requirement_id',x.logical_requirement_id,'verified_at',x.verified_at,'subject_id',x.equipment_id,'result',x.result,'scheduled_due_date',x.scheduled_due_date,'recorded_at',x.recorded_at,'verification_state',x.status,'source_type','calibration_record') from public.factory_mesti_calibration_records x where x.calibrated_date between p_from and p_to
union all
select jsonb_build_object('id','operator_hygiene:'||s.id,'record_id',s.id,'module','operator_hygiene','label','Operator hygiene session evidence','business_date',s.inspection_date,'record_status',s.status,'submitted_at',s.submitted_at,'verified_at',s.verified_at,'inspected_count',c.inspected,'non_compliant_count',c.failed,'source_type','daily_session') from public.factory_mesti_operator_hygiene_sessions s cross join lateral(select count(*) inspected,count(*) filter(where overall_result='non_compliant') failed from public.factory_mesti_operator_hygiene_entries where session_id=s.id)c where s.inspection_date between p_from and p_to
union all
select jsonb_build_object('id','waste_disposal:session_'||s.id,'record_id',s.id,'module','waste_disposal','label','Waste disposal session evidence','business_date',s.disposal_date,'record_status',s.status,'submitted_at',s.submitted_at,'verified_at',s.verified_at,'completed_count',(select count(*) from public.factory_mesti_waste_disposal_events where session_id=s.id),'source_type','daily_session') from public.factory_mesti_waste_disposal_sessions s where s.disposal_date between p_from and p_to
union all
select jsonb_build_object('id','waste_disposal:event_'||e.id,'record_id',e.id,'parent_id','waste_disposal:session_'||s.id,'module','waste_disposal','label','Disposal event','business_date',s.disposal_date,'record_status',s.status,'subject_id',e.location_id,'disposed_at',e.disposed_at,'source_type','disposal_event') from public.factory_mesti_waste_disposal_events e join public.factory_mesti_waste_disposal_sessions s on s.id=e.session_id where s.disposal_date between p_from and p_to
union all
select value from feedx_integrations.mesti_resource_occurrences(p_from,p_to) value where value->>'module'='health_declaration'
union all
select jsonb_build_object('id','food_processing_control:qc_'||p.id||'_'||e.id,'record_id',e.id,'parent_id','food_processing_control:'||p.id,'module','food_processing_control','label',e.qc_name,'business_date',p.end_date,'production_id',p.id,'requirement_id',e.sop_qc_check_id,'qc_type',e.qc_type,'is_required',e.is_required,'checklist_result',e.checklist_result,'remarks_present',nullif(btrim(e.remarks),'') is not null,'checked_at',e.checked_at,'verification_state',p.verification_status,'verified_at',p.verified_at,'source_type',case when e.production_id=p.id then 'production_qc' else 'legacy_job_order_qc' end) from public.factory_productions p join public.factory_production_qc_results e on (e.production_id=p.id or (e.production_id is null and e.job_order_id=p.job_order_id)) where p.status='completed' and p.end_date between p_from and p_to
union all
select jsonb_build_object('id','finished_product_storage_control:batch_'||b.id,'record_id',b.id,'parent_id','finished_product_storage_control:'||p.id,'module','finished_product_storage_control','label','Finished product storage provenance','business_date',p.end_date,'production_id',p.id,'batch_no',b.batch_no,'manufacturing_date',b.manufacturing_date,'expiry_date',b.expiry_date,'subject_id',b.storage_location_id,'source_type','production_batch') from public.factory_productions p join public.factory_finished_good_batch_balances b on b.production_id=p.id and b.source_type='production' where p.status='completed' and p.end_date between p_from and p_to
$$;
revoke all on function feedx_integrations.mesti_resource_evidence(date,date) from public,anon,authenticated;

create function feedx_integrations.mesti_resource_schedules(p_from date,p_to date) returns setof jsonb language sql stable security definer set search_path=public,pg_temp as $$
select jsonb_build_object('id','cleaning_of_area:'||x.due_date||':'||x.id,'module','cleaning_of_area','label','Issued cleaning schedule','business_date',x.due_date,'due_on',x.due_date,'requirement_id',x.requirement_id,'logical_requirement_id',x.logical_requirement_id,'subject_id',x.location_id,'version',x.requirement_snapshot->'version_no','recurrence',x.requirement_snapshot->'recurrence_type','weekdays',x.requirement_snapshot->'recurrence_weekdays','effective_from',x.requirement_snapshot->'effective_from','effective_until',x.requirement_snapshot->'effective_until','schedule_basis','issued_snapshot','source_type','scheduled') from public.factory_mesti_cleaning_occurrences x where x.due_date between p_from and p_to
union all
select jsonb_build_object('id','cleaning_of_equipment:'||x.due_date||':'||x.id,'module','cleaning_of_equipment','label','Issued cleaning schedule','business_date',x.due_date,'due_on',x.due_date,'requirement_id',x.requirement_id,'logical_requirement_id',x.logical_requirement_id,'subject_id',x.equipment_id,'version',x.requirement_snapshot->'version_no','recurrence',x.requirement_snapshot->'recurrence_type','weekdays',x.requirement_snapshot->'recurrence_weekdays','effective_from',x.requirement_snapshot->'effective_from','effective_until',x.requirement_snapshot->'effective_until','schedule_basis','issued_snapshot','source_type',x.source_type,'production_id',x.production_id) from public.factory_mesti_equipment_cleaning_occurrences x where x.due_date between p_from and p_to
union all
select jsonb_build_object('id','cleaning_of_area:'||d.day::date||':'||(r->>'requirement_id')||':'||subject,'module','cleaning_of_area','label','Requirement schedule','business_date',d.day::date,'due_on',d.day::date,'requirement_id',r->'requirement_id','logical_requirement_id',r->'logical_requirement_id','subject_id',subject,'version',r->'version','recurrence',r->'recurrence','weekdays',r->'weekdays','effective_from',r->'effective_from','effective_until',r->'effective_until','schedule_basis','current_requirement_binding','source_type','scheduled') from feedx_integrations.mesti_resource_requirements(p_from,p_to) r cross join generate_series(p_from,p_to,interval '1 day') d(day) cross join lateral jsonb_array_elements_text(r->'subject_ids') j(subject) where r->>'module'='cleaning_of_area' and r->>'record_status'='active' and (r->>'effective_from')::date<=d.day::date and (r->>'effective_until' is null or d.day::date<(r->>'effective_until')::date) and public.factory_mesti_recurrence_due(r->>'recurrence',array(select value::integer from jsonb_array_elements_text(case when jsonb_typeof(r->'weekdays')='array' then r->'weekdays' else '[]'::jsonb end)),d.day::date) and exists(select 1 from public.factory_storage_locations l where l.id=subject::uuid and l.status='active') and not exists(select 1 from public.factory_mesti_cleaning_occurrences x where x.logical_requirement_id=(r->>'logical_requirement_id')::uuid and x.location_id=subject::uuid and x.due_date=d.day::date)
union all
select jsonb_build_object('id','cleaning_of_equipment:'||d.day::date||':'||(r->>'requirement_id')||':'||subject,'module','cleaning_of_equipment','label','Requirement schedule','business_date',d.day::date,'due_on',d.day::date,'requirement_id',r->'requirement_id','logical_requirement_id',r->'logical_requirement_id','subject_id',subject,'version',r->'version','recurrence',r->'recurrence','weekdays',r->'weekdays','effective_from',r->'effective_from','effective_until',r->'effective_until','schedule_basis','current_requirement_binding','source_type','scheduled') from feedx_integrations.mesti_resource_requirements(p_from,p_to) r cross join generate_series(p_from,p_to,interval '1 day') d(day) cross join lateral jsonb_array_elements_text(r->'subject_ids') j(subject) where r->>'module'='cleaning_of_equipment' and r->>'record_status'='active' and (r->>'effective_from')::date<=d.day::date and (r->>'effective_until' is null or d.day::date<(r->>'effective_until')::date) and public.factory_mesti_recurrence_due(r->>'recurrence',array(select value::integer from jsonb_array_elements_text(case when jsonb_typeof(r->'weekdays')='array' then r->'weekdays' else '[]'::jsonb end)),d.day::date) and exists(select 1 from public.factory_equipment e join public.factory_storage_locations l on l.id=e.current_location_id where e.id=subject::uuid and e.status='active' and l.status='active') and not exists(select 1 from public.factory_mesti_equipment_cleaning_occurrences x where x.logical_requirement_id=(r->>'logical_requirement_id')::uuid and x.equipment_id=subject::uuid and x.due_date=d.day::date and x.source_type='scheduled')
union all
select jsonb_build_object('id','waste_disposal:'||d.day::date||':'||(r->>'requirement_id')||':'||subject,'module','waste_disposal','label','Requirement schedule','business_date',d.day::date,'due_on',d.day::date,'requirement_id',r->'requirement_id','logical_requirement_id',r->'logical_requirement_id','subject_id',subject,'version',r->'version','recurrence',r->'recurrence','weekdays',r->'weekdays','effective_from',r->'effective_from','effective_until',r->'effective_until','schedule_basis','current_requirement_binding','source_type','scheduled','required_count',r->'required_count') from feedx_integrations.mesti_resource_requirements(p_from,p_to) r cross join generate_series(p_from,p_to,interval '1 day') d(day) cross join lateral jsonb_array_elements_text(r->'subject_ids') j(subject) where r->>'module'='waste_disposal' and r->>'record_status'='active' and (r->>'effective_from')::date<=d.day::date and (r->>'effective_until' is null or d.day::date<(r->>'effective_until')::date) and public.factory_mesti_recurrence_due(r->>'recurrence',array(select value::integer from jsonb_array_elements_text(case when jsonb_typeof(r->'weekdays')='array' then r->'weekdays' else '[]'::jsonb end)),d.day::date) and exists(select 1 from public.factory_storage_locations l where l.id=subject::uuid and l.status='active')
union all
select jsonb_build_object('id','calibration:'||d.day::date||':'||r.id,'module','calibration','label','Calibration schedule','business_date',d.day::date,'due_on',coalesce(public.factory_mesti_calibration_due_date(pass.calibrated_date,r.interval_months),r.effective_from),'requirement_id',r.id,'logical_requirement_id',r.logical_requirement_id,'subject_id',r.equipment_id,'version',r.version_no,'interval_months',r.interval_months,'effective_from',r.effective_from,'effective_until',r.effective_until,'schedule_basis','verified_pass_as_of_business_date','source_type','interval_months') from public.factory_mesti_calibration_requirements r cross join generate_series(p_from,p_to,interval '1 day') d(day) left join lateral(select c.calibrated_date from public.factory_mesti_calibration_records c where c.logical_requirement_id=r.logical_requirement_id and c.status='verified' and c.result='pass' and c.calibrated_date<=d.day::date and c.verified_at<(d.day::date+1)::timestamp at time zone 'Asia/Kuala_Lumpur' order by c.verified_at desc,c.created_at desc,c.id limit 1) pass on true where r.status='active' and r.effective_from<=d.day::date and (r.effective_until is null or d.day::date<r.effective_until)
union all
select jsonb_build_object('id','cleaning_of_equipment:production_'||p.id||'_'||b.equipment_id,'module','cleaning_of_equipment','label','Production End cleaning binding','business_date',p.end_date,'due_on',p.end_date,'production_id',p.id,'subject_id',b.equipment_id,'production_sop_id',p.production_sop_id,'sop_version',p.sop_version,'schedule_basis','pinned_sop_equipment_binding','source_type','after_production') from public.factory_productions p join public.factory_production_sops s on s.id=p.production_sop_id and s.version=p.sop_version join public.factory_production_sop_equipment b on b.sop_id=s.id where p.status='completed' and p.end_date between p_from and p_to and not exists(select 1 from public.factory_mesti_equipment_cleaning_occurrences o where o.production_id=p.id and o.equipment_id=b.equipment_id and o.source_type='after_production')
union all
select jsonb_build_object('id',m.module||':'||p.id,'module',m.module,'label','Production End compliance context','business_date',p.end_date,'due_on',p.end_date,'production_id',p.id,'production_sop_id',p.production_sop_id,'sop_version',p.sop_version,'sop_resolved',exists(select 1 from public.factory_production_sops s where s.id=p.production_sop_id and s.version=p.sop_version),'schedule_basis','canonical_production_end','source_type','production_end') from public.factory_productions p cross join (values('food_processing_control'),('finished_product_storage_control'))m(module) where p.status='completed' and p.end_date between p_from and p_to
union all
select jsonb_build_object('id','cleaning_of_equipment:unresolved_'||p.id,'module','cleaning_of_equipment','label','Unresolved Production End equipment schedule','business_date',p.end_date,'due_on',p.end_date,'production_id',p.id,'production_sop_id',p.production_sop_id,'sop_version',p.sop_version,'schedule_basis','pinned_sop_equipment_coverage','source_type','after_production','entry_kind','coverage_gap','data_availability','unavailable','limitation','Pinned SOP or Equipment bindings cannot be resolved. No subject, requirement or missing occurrence is inferred.') from public.factory_productions p where p.status='completed' and p.end_date between p_from and p_to and (not exists(select 1 from public.factory_production_sops s where s.id=p.production_sop_id and s.version=p.sop_version) or not exists(select 1 from public.factory_production_sop_equipment b where b.sop_id=p.production_sop_id))

$$;
revoke all on function feedx_integrations.mesti_resource_schedules(date,date) from public,anon,authenticated;

create function feedx_integrations.mesti_resource_rows(p_resource text,p_from date,p_to date) returns setof jsonb
language plpgsql stable security definer set search_path=public,pg_temp as $$
begin
 case p_resource
 when 'requirements' then return query select * from feedx_integrations.mesti_resource_requirements(p_from,p_to);
 when 'occurrences' then return query select * from feedx_integrations.mesti_resource_occurrences(p_from,p_to);
 when 'evidence' then return query select * from feedx_integrations.mesti_resource_evidence(p_from,p_to);
 when 'schedules' then return query select * from feedx_integrations.mesti_resource_schedules(p_from,p_to);
 when 'statuses' then return query select jsonb_build_object('id',v->'id','record_id',v->'record_id','module',v->'module','label','Saved lifecycle state','business_date',v->'business_date','record_status',v->'record_status','state_source',v->'state_source','verification_state',v->'verification_state','completed_at',v->'completed_at','submitted_at',v->'submitted_at','verified_at',v->'verified_at') from feedx_integrations.mesti_resource_occurrences(p_from,p_to) v;
 else raise exception using errcode='42501',message='Resource unavailable.';
 end case;
end $$;
revoke all on function feedx_integrations.mesti_resource_rows(text,date,date) from public,anon,authenticated;


